import { setUiAttribute, setUiText } from "./placementLocale";

/** Explicit adapter for labels generated by the shared, language-neutral control helpers. */
export function bindUiControl<T extends HTMLElement>(
  control: T,
  label: string,
  enumOptions = false,
): T {
  const wrapper = control.closest("label");
  const caption = wrapper?.querySelector("span");
  if (caption) setUiText(caption, label);
  setUiAttribute(control, "aria-label", label);
  if (enumOptions && control instanceof HTMLSelectElement) {
    for (const option of control.options)
      setUiText(option, option.textContent ?? "");
  }
  return control;
}
